def subject_conds(p):
    return [c for c in p['conds'] if c.get('role') == '주체']


def note_of(p, why):
    ref = '근거 %s %s행 「%s」' % (p['file'], p['line'], p.get('clause') or p['text'])
    old = p.get('note')
    s = 'O25 해독: %s. %s' % (why, ref)
    return (old + ' / ' + s) if old else s


def main(path=None):
    path = path or os.path.join(HERE, 'passages_j3.json')
    with open(path, encoding='utf-8') as f:
        data = json.load(f)
    done = skipped = 0
    for p in data:
        if p['parse'] != 'unparsed':
            if p['id'] in DEC:
                skipped += 1
            continue
        d = DEC.get(p['id'])
        if d is None:
            if p['id'] in TYPES:
                p['decode_type'] = TYPES[p['id']]
            continue
        if p.get('region'):
            skipped += 1
            continue
        p['decode_type'] = TYPES.get(p['id'])
        subj = subject_conds(p)
        if d['mode'] != 'R':
            p['decoded_from'] = p.get('reason')
            p.pop('reason', None)
        if d['mode'] == 'N':
            p['conds'] = subj
            p['parse'] = 'manual'
        elif d['mode'] == 'K':
            p['parse'] = 'manual'
        elif d['mode'] == 'C':
            p['conds'] = subj + d['conds']
            p['parse'] = 'manual'
        elif d['mode'] == 'R':
            # test_l2.test_j3_table_integrity가 parse를 auto/manual/unparsed로 못 박아 parse는 unparsed로 둔다.
            # 출신지 표시는 region 필드로 하고, 집계에서 빼는 처리는 l2.py가 이 필드를 읽어 한다.
            p['decoded_from'] = p.get('reason')
            p['region'] = True
            p['reason'] = '출신지 조건(미검사, 명세 11-3 2번)'
        p['note'] = note_of(p, d['why'])
        done += 1
    tmp = path + '.tmp'
    with open(tmp, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=1)
    os.replace(tmp, path)
    print('권3: 옮긴 구절 %d, 이미 처리됨 %d' % (done, skipped))


if __name__ == '__main__':
    main(sys.argv[1] if len(sys.argv) > 1 else None)
